<?= $this->extend('layouts/staff') ?><?= $this->section('content') ?><?= view('components/page_header',['title'=>$title,'breadcrumb'=>'Users Management']) ?><?php if(session('error')): ?><p class="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-800"><?= esc(session('error')) ?></p><?php endif ?><form class="card grid gap-4 p-5 sm:grid-cols-2" method="post" action="<?= isset($user)?site_url('users/'.$user->id.'/update'):site_url('users') ?>"><?= csrf_field() ?><?php foreach(['first_name'=>'First name','middle_name'=>'Middle name','last_name'=>'Last name','username'=>'Username','mobile_no'=>'Mobile number','email'=>'Email','birthdate'=>'Birthdate','address'=>'Address'] as $field=>$label): ?><div><label class="form-label" for="<?= $field ?>"><?= esc($label) ?></label><input class="form-control" id="<?= $field ?>" name="<?= $field ?>" value="<?= esc(old($field,$user->$field??'')) ?>" <?= $field==='birthdate'?'type="date"':($field==='mobile_no'?'type="tel"':'') ?> <?= $field==='username'&&isset($user)?'readonly':'' ?>></div><?php endforeach ?><div><label class="form-label" for="sex">Sex</label><select class="form-control" id="sex" name="sex"><option value="">Unspecified</option><?php foreach(['female'=>'Female','male'=>'Male'] as $key=>$label): ?><option value="<?= $key ?>" <?= old('sex',$user->sex??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select></div><div><label class="form-label" for="purok_id">Purok</label><select class="form-control" id="purok_id" name="purok_id"><option value="">—</option><?php foreach($puroks as $p): ?><option value="<?= $p['id'] ?>" <?= (string)old('purok_id',$user->purok_id??'')===(string)$p['id']?'selected':'' ?>><?= esc($p['name']) ?></option><?php endforeach ?></select></div><div><label class="form-label" for="role">Role</label><select class="form-control" id="role" name="role"><?php if($isAdmin): foreach(['admin'=>'Administrator','bhw'=>'BHW','parent'=>'Parent / Guardian'] as $key=>$label): ?><option value="<?= $key ?>" <?= $user&&$user->inGroup($key)?'selected':'' ?>><?= $label ?></option><?php endforeach; else: ?><option value="parent" selected>Parent / Guardian</option><?php endif ?></select></div><div class="flex items-end"><button class="btn-primary w-full"><?= isset($user)?'Save Changes':'Create Account' ?></button></div><?php if(!isset($user)): ?><p class="sm:col-span-2 text-xs text-gray-500">Parent accounts receive no password and sign in by SMS OTP. Staff receive a temporary password that must be changed at first sign-in.</p><?php endif ?></form><?= $this->endSection() ?>
